package net.minecraft.core.registries;public class BuiltInRegistries {public static final java.util.Map<net.minecraft.resources.ResourceLocation,net.minecraft.world.item.Item> items=new java.util.HashMap<>();public static net.minecraft.core.DefaultedRegistry<net.minecraft.world.item.Item> ITEM=new net.minecraft.core.DefaultedRegistry<>(){public net.minecraft.world.item.Item get(net.minecraft.resources.ResourceLocation id){return items.getOrDefault(id,net.minecraft.world.item.Items.AIR);}public net.minecraft.resources.ResourceLocation getKey(net.minecraft.world.item.Item i){return items.entrySet().stream().filter(e->e.getValue()==i).map(java.util.Map.Entry::getKey).findFirst().orElse(net.minecraft.resources.ResourceLocation.tryParse("minecraft:air"));}};}